def render(family, f, lang, variant):
    it = lang == "it"
    labels = dict(zip(LABELS["routing"], ("fatturazione", "consegna", "accesso", "generale") if it else
                      ("billing", "delivery", "account access", "general")))
    params = {**f, "order": " > ".join(labels[k] for k in f.get("priority", []))}
    instruction = RULES[family][variant][int(it)].format(**params)
    # Fact statements vary independently of rule phrasing and contain no gold labels.
    short = lambda x: ("ignoto" if it else "unknown") if x is None else (("sì" if x else "no") if it else ("yes" if x else "no"))
    if family == "routing":
        if variant % 2:
            statements = [("C'è" if f[k] else "Non c'è") + " un problema di " + labels[k] + "." if it else
                          ("There is" if f[k] else "There is no") + " " + ("a " if f[k] else "") + labels[k] + " issue."
                          for k in ("billing", "delivery", "access")]
        else:
            statements = [labels[k] + ": " + short(f[k]) for k in ("billing", "delivery", "access")]
        statements.append(("Importo: " if it else "Amount: ") + str(f["amount"]) + " EUR.")
        q = {"type": "choice", "criteria": labels}
    elif family == "refund":
        if variant % 2:
            elapsed = ("Non so quando è arrivato il pacco." if it else "I do not know when the parcel arrived.") if f["days"] is None else (
                f"Ho ricevuto il pacco {f['days']} giorni fa." if it else f"I received the parcel {f['days']} days ago.")
            proof = ("Non so se ho conservato la ricevuta." if it else "I am unsure whether I kept the receipt.") if f["proof"] is None else (
                ("Ho la ricevuta." if it else "I have the receipt.") if f["proof"] else ("Non ho la ricevuta." if it else "I do not have the receipt."))
            statements = [elapsed, proof]
        else:
            statements = [("Giorni dalla consegna: " if it else "Days since delivery: ") +
                          (("ignoti" if it else "unknown") if f["days"] is None else str(f["days"])),
                          ("Prova di acquisto: " if it else "Proof of purchase: ") + short(f["proof"])]
        q = {"type": "choice", "criteria": dict(zip(LABELS[family],
             ("approva il rimborso", "rifiuta il rimborso", "richiedi chiarimenti") if it else
             ("approve refund", "deny refund", "ask for clarification")))}
    elif family == "urgency":
        statements = [(f"Mi serve una risposta entro {f['hours']} ore." if it else f"I need a response within {f['hours']} hours.") if variant % 2 else
                      (("Ore fino alla scadenza: " if it else "Hours until deadline: ") + str(f["hours"]))]
        q = {"type": "score", "criteria": ["bassa", "media", "alta"] if it else ["low", "medium", "high"]}
    else:
        verification = (("La verifica dell'identità è stata completata." if it else "Identity verification has been completed.") if f["verified"] else
                        ("La verifica dell'identità non è stata completata." if it else "Identity verification has not been completed."))
        statements = [verification, f"Importo richiesto: {f['amount']} EUR." if it else f"Requested amount: {f['amount']} EUR.",
                      f"Si sono verificati {f['attempts']} tentativi falliti." if it else f"There have been {f['attempts']} failed attempts."]
        q = {"type": "noul", "criteria": {"false": "gestione automatica" if it else "automatic handling",
                                          "true": "passaggio a un operatore" if it else "human handoff"}}
    random.Random(sha([family, f, variant])).shuffle(statements)
    if variant % 3 == 0:
        state = {"riepilogo" if it else "summary": statements}
    elif variant % 3 == 1:
        state = ("Richiesta di assistenza: " if it else "Support request: ") + " ".join(statements)
    else:
        state = ("Note del caso:\n" if it else "Case notes:\n") + "\n".join("- " + s for s in statements)
    q["instructions"] = instruction
    return state, q


def generate():
    prior = generate_v1()
    seen = {sha([r["supervision"]["decision"]["task"], r["provenance"]["facts"]])
            for rows in prior.values() for r in rows}
    result = {s: [] for s in SIZES}
    for family in FAMILIES:
        rng = random.Random("practical-v2:" + family)
        for split, size in SIZES.items():
            for index in range(size):
                wanted = LABELS[family][index % len(LABELS[family])]
                variant = BANKS[split][(index // len(LABELS[family])) % len(BANKS[split])]
                for _ in range(100000):
                    f = facts(family, rng)
                    signature = sha([family, f])
                    if signature not in seen and oracle(family, f) == wanted:
                        break
                else:
                    raise ValueError("Insufficient unique configurations")
                seen.add(signature)
                pair = "practical-v2/" + family + "/" + signature
                for lang in ("en", "it"):
                    state, question = render(family, f, lang, variant)
                    if question["type"] == "choice":
                        keys = list(question["criteria"])
                        random.Random(signature).shuffle(keys)
                        question["criteria"] = {k: question["criteria"][k] for k in keys}
                    result[split].append({"record_id": pair + "/" + lang, "group_id": pair,
                        "language": lang, "source_family": "practical_" + family, "split": split,
                        "schema_family": "practical_v2." + family,
                        "request": {"state": state, "questions": {"decision": question}},
                        "supervision": {"decision": {"gold": wanted, "task": family}},
                        "provenance": {"parallel_record": pair, "facts": f, "generator": "practical-v2",
                                       "template_id": variant, "template_bank": split}})
    return result
